// Builds app/data/utility-classes.json, plus a typed wrapper module beside it, from the installed
// @energysage/es-ds-styles package.
// Each partial is compiled on its own and the class names are read from the resulting CSS, since
// most utilities are generated by @each loops over Sass maps and never appear literally in the source.
// Usage: node scripts/generate-utility-classes.mjs (runs automatically before dev, build, and generate)

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import postcss from 'postcss';
import * as sass from 'sass';

const PACKAGE_NAME = '@energysage/es-ds-styles';
const docsRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const jsonPath = join(docsRoot, 'app/data/utility-classes.json');
const modulePath = join(docsRoot, 'app/data/utility-classes.ts');

// Resolves through `make symlink`, so local es-ds-styles edits are picked up on the next run.
const packageJsonPath = createRequire(import.meta.url).resolve(`${PACKAGE_NAME}/package.json`);
const packageRoot = dirname(packageJsonPath);
const scssRoot = join(packageRoot, 'scss');
const { version } = JSON.parse(readFileSync(packageJsonPath, 'utf8'));

// The package's own deprecation warnings are surfaced by its build; repeating them here only clutters dev startup.
const compile = (path) => sass.compile(path, { logger: sass.Logger.silent }).css;
const compileString = (source) =>
    sass.compileString(source, { loadPaths: [scssRoot], logger: sass.Logger.silent }).css;

// Utilities partials are read from the @use lines in _utilities.scss so only partials that ship in the bundle are listed.
const utilitySources = [
    ...readFileSync(join(scssRoot, '_utilities.scss'), 'utf8').matchAll(/@use\s+"utilities\/([\w-]+)"/g),
].map(([, name]) => ({ name, path: `utilities/_${name}.scss` }));

// Other partials with standalone helper classes; `include` narrows a partial to the classes worth listing.
const EXTRA_SOURCES = [
    { name: 'typography', path: '_type.scss' },
    { name: 'images', path: '_images.scss' },
    { name: 'order', path: '_grid.scss', include: /^order-/ },
    { name: 'code', path: '_code.scss', include: /^pre-scrollable$/ },
];

const breakpoints = {};
postcss
    .parse(
        compileString(
            '@use "variables"; @each $name, $width in variables.$grid-breakpoints { .#{$name} { min-width: $width; } }',
        ),
    )
    .walkRules((rule) => {
        rule.walkDecls('min-width', (decl) => {
            breakpoints[rule.selector.slice(1)] = decl.value;
        });
    });
// The smallest breakpoint has no infix, matching breakpoint-infix() in mixins/_breakpoints.scss.
const infixBreakpoints = Object.keys(breakpoints).slice(1);

const getAtRules = (node) => {
    const atRules = [];
    for (let parent = node.parent; parent && parent.type === 'atrule'; parent = parent.parent) {
        atRules.unshift(`@${parent.name} ${parent.params}`);
    }
    return atRules;
};

const CLASS_PATTERN = /\.(-?[_a-zA-Z][\w-]*)/g;

// Numeric collation keeps sizes in order (`w-25`, `w-50`, `w-100`); a fixed locale keeps output identical across machines.
const nameCollator = new Intl.Collator('en', { numeric: true });

// Partials listed here become several categories. Each class goes to the first group whose `properties` pattern
// matches every property it declares; a group without a pattern takes the rest.
const CATEGORY_SPLITS = {
    spacing: [
        { name: 'margin', properties: /^margin/ },
        { name: 'padding', properties: /^padding/ },
    ],
    text: [{ name: 'text-color', properties: /^color$/ }, { name: 'text-style' }],
};

const partialCategories = [...utilitySources, ...EXTRA_SOURCES].flatMap(({ name, path, include }) => {
    const sourcePath = join(scssRoot, path);
    const classes = new Map();
    const ensureClass = (className) => {
        if (!classes.has(className)) {
            classes.set(className, { name: className, rules: [] });
        }
        return classes.get(className);
    };

    postcss.parse(compile(sourcePath)).walkRules((rule) => {
        const atRules = getAtRules(rule);
        const declarations = rule.nodes
            .filter((node) => node.type === 'decl')
            .map((decl) => `${decl.prop}: ${decl.value}${decl.important ? ' !important' : ''}`);

        for (const selector of rule.selectors) {
            const classNames = [...selector.matchAll(CLASS_PATTERN)].map(([, className]) => className);
            if (!classNames.length) continue;
            classNames.forEach(ensureClass);
            // A rule belongs to the selector's subject (its last class), e.g. `.embed-responsive .embed-responsive-item`.
            ensureClass(classNames.at(-1)).rules.push({ selector, atRules, declarations });
        }
    });

    // Drops classes outside `include`, and classes that only appear as another class's ancestor (no rules of their own).
    for (const [className, entry] of classes) {
        if (!entry.rules.length || (include && !include.test(className))) classes.delete(className);
    }

    // Variants are matched by name rather than media query because some base classes (e.g. `font-size-h1`) carry
    // their own responsive rules; requiring the base class to exist keeps names like `shadow-sm` from matching.
    const variantsByBase = new Map();
    for (const className of classes.keys()) {
        for (const [breakpointIndex, breakpoint] of infixBreakpoints.entries()) {
            const infix = `-${breakpoint}-`;
            const index = className.indexOf(infix);
            if (index === -1) continue;
            const prefix = className.slice(0, index);
            const suffix = className.slice(index + infix.length);
            const base = `${prefix}-${suffix}`;
            if (!classes.has(base)) continue;
            if (!variantsByBase.has(base))
                variantsByBase.set(base, { display: `${prefix}-*-${suffix}`, variants: [] });
            variantsByBase.get(base).variants.push({ className, breakpointIndex });
            classes.delete(className);
            break;
        }
    }

    const entries = [...classes.values()].map(({ name: className, rules }) => {
        const flags = new Set(
            rules.flatMap((rule) => rule.declarations.map((declaration) => declaration.endsWith(' !important'))),
        );
        // A single flag per class is only accurate while no class mixes important and plain declarations.
        if (flags.size > 1) {
            throw new Error(`utility-classes: \`${className}\` in ${path} mixes !important and plain declarations`);
        }
        const important = flags.has(true);
        const group = variantsByBase.get(className);
        if (!group) return { name: className, important, rules };
        const variants = group.variants
            .sort((a, b) => a.breakpointIndex - b.breakpointIndex)
            .map((variant) => variant.className);
        return { name: className, display: group.display, variants, important, rules };
    });
    entries.sort((a, b) => nameCollator.compare(a.name, b.name));

    const source = relative(packageRoot, sourcePath);
    const splits = CATEGORY_SPLITS[name];
    if (!splits) return [{ name, source, classes: entries }];

    const groups = splits.map((split) => ({ split, category: { name: split.name, source, classes: [] } }));
    for (const entry of entries) {
        const properties = entry.rules.flatMap((rule) =>
            rule.declarations.map((declaration) => declaration.split(':')[0]),
        );
        const group = groups.find(
            ({ split }) => !split.properties || properties.every((property) => split.properties.test(property)),
        );
        if (!group) {
            throw new Error(`utility-classes: \`${entry.name}\` in ${path} matches none of its split categories`);
        }
        group.category.classes.push(entry);
    }
    return groups.map(({ category }) => category);
});

// Deprecation is defined once, in es-ds-styles' scss/_deprecated.scss; the docs pages read this same export.
const deprecatedLists = {};
postcss.parse(compile(join(scssRoot, 'modules/deprecated.module.scss'))).walkDecls((decl) => {
    deprecatedLists[decl.prop] = decl.value.split(/\s+/);
});
// Maps an item from each list to the base class names it produces; breakpoint variants follow their base class.
const DEPRECATED_CLASS_PATTERNS = {
    spacers: (key) => new RegExp(`^[mp][trblxy]?-n?${key}$`),
    'font-sizes': (key) => new RegExp(`^font-size-${key}$`),
    colors: (color) => new RegExp(`^(text|bg|border)-${color}$`),
    classes: (className) => new RegExp(`^${className}$`),
};
const deprecatedPatterns = Object.entries(deprecatedLists).flatMap(([list, items]) => {
    const toPattern = DEPRECATED_CLASS_PATTERNS[list];
    if (!toPattern) throw new Error(`utility-classes: no class pattern for deprecated list \`${list}\``);
    return items.map((item) => ({ list, item, pattern: toPattern(item) }));
});
// An item matching nothing is a typo or a removed class, either of which would silently shrink the deprecated list.
const allClassNames = partialCategories.flatMap((category) => category.classes.map((entry) => entry.name));
for (const { list, item, pattern } of deprecatedPatterns) {
    if (!allClassNames.some((className) => pattern.test(className))) {
        throw new Error(`utility-classes: deprecated ${list} item \`${item}\` matches no utility class`);
    }
}
const isDeprecated = (entry) => deprecatedPatterns.some(({ pattern }) => pattern.test(entry.name));

const buildCategories = (includeEntry) =>
    partialCategories
        .map(({ name, source, classes }) => ({ name, source, classes: classes.filter(includeEntry) }))
        .filter(({ classes }) => classes.length)
        .map(({ name, source, classes }) => ({
            // Names double as display labels, so partial names like `stretched-link` read as `stretched link`.
            name: name.replaceAll('-', ' '),
            source,
            allClassesUseImportant: classes.every((entry) => entry.important),
            classes,
        }))
        .sort((a, b) => nameCollator.compare(a.name, b.name));
const categories = buildCategories((entry) => !isDeprecated(entry));
const deprecated = buildCategories(isDeprecated);

// Pages import from this module rather than the JSON. The interfaces describe the objects built above and must be
// edited alongside them; the typed assignment at the end makes `make typecheck` fail if the two drift apart.
const typedModule = `// Generated by scripts/generate-utility-classes.mjs; edit the script, not this file.
import data from './utility-classes.json';

export interface UtilityClassRule {
    /** Full selector, e.g. \`a.bg-primary:hover\` or \`.embed-responsive .embed-responsive-item\`. */
    selector: string;
    /** Enclosing at-rules, outermost first, e.g. \`@media (min-width: 768px)\`. */
    atRules: string[];
    /** e.g. \`margin-top: 1rem !important\` */
    declarations: string[];
}

export interface UtilityClass {
    name: string;
    /** The name with its breakpoint infix shown as \`*\`, e.g. \`d-*-inline\`. Present only alongside \`variants\`. */
    display?: string;
    /** Breakpoint variants in breakpoint order, e.g. \`d-sm-inline\`, \`d-md-inline\`. */
    variants?: string[];
    /** Whether the declarations use \`!important\`; no class mixes important and plain declarations. */
    important: boolean;
    /** Rules for the base class only; each variant repeats them inside its breakpoint's media query. */
    rules: UtilityClassRule[];
}

export interface UtilityClassCategory {
    /** Partial name with hyphens as spaces, e.g. \`stretched link\`; split partials become several, e.g. \`text color\`. */
    name: string;
    /** Path within the es-ds-styles package, e.g. \`scss/_type.scss\`; split categories share their partial's path. */
    source: string;
    /** True when every class uses \`!important\`; otherwise check each class's \`important\`. */
    allClassesUseImportant: boolean;
    /** Sorted by name. */
    classes: UtilityClass[];
}

export interface UtilityClassData {
    package: string;
    version: string;
    /** \`$grid-breakpoints\` from es-ds-styles, smallest first, e.g. \`{ xs: '0', sm: '576px' }\`. */
    breakpoints: Record<string, string>;
    /** Classes that are not deprecated. */
    categories: UtilityClassCategory[];
    /** Deprecated classes, grouped the same way; defined in es-ds-styles' \`scss/_deprecated.scss\`. */
    deprecated: UtilityClassCategory[];
}

export const utilityClassData: UtilityClassData = data;
`;

mkdirSync(dirname(jsonPath), { recursive: true });
writeFileSync(
    jsonPath,
    `${JSON.stringify({ package: PACKAGE_NAME, version, breakpoints, categories, deprecated }, null, 4)}\n`,
);
writeFileSync(modulePath, typedModule);

const countClasses = (list) => {
    const entries = list.flatMap((category) => category.classes);
    const variantCount = entries.reduce((total, entry) => total + (entry.variants?.length ?? 0), 0);
    return `${entries.length} (+${variantCount} breakpoint variants)`;
};
console.log(
    `utility-classes: ${countClasses(categories)} classes and ${countClasses(deprecated)} deprecated from ${PACKAGE_NAME}@${version} → ${relative(docsRoot, dirname(jsonPath))}`,
);
